'use client';
/* eslint-disable react-hooks/set-state-in-effect, react-hooks/use-memo */

import { FormEvent, ReactNode, useCallback, useEffect, useState } from 'react';
import Link from 'next/link';

import { api, ApiError, messageFromError } from '../lib/api';
import { formatDate, formatDateTime, formatMoney, shortId, timeFromMinutes } from '../lib/format';

type Data = Record<string, unknown>;
type Page = { path: string; label: string; capability: Capability };
type Capability = 'admin' | 'kitchen' | 'dispatch' | 'driver' | 'billing';

interface Staff {
  id: string;
  email: string;
  role: { code: string; name: string };
}

const pages: Page[] = [
  { path: '/dashboard', label: 'Dashboard', capability: 'admin' },
  { path: '/catalogue/dishes', label: 'Catalogue', capability: 'admin' },
  { path: '/pricing', label: 'Pricing', capability: 'admin' },
  { path: '/companies', label: 'Companies', capability: 'admin' },
  { path: '/employees', label: 'Employees', capability: 'admin' },
  { path: '/menu', label: 'Menu', capability: 'admin' },
  { path: '/orders', label: 'Orders', capability: 'admin' },
  { path: '/kitchen', label: 'Kitchen', capability: 'kitchen' },
  { path: '/dispatch', label: 'Dispatch', capability: 'dispatch' },
  { path: '/billing', label: 'Billing', capability: 'billing' },
  { path: '/settings', label: 'Settings', capability: 'admin' },
  { path: '/reference/allergens', label: 'Reference data', capability: 'admin' },
  { path: '/driver', label: 'My deliveries', capability: 'driver' },
];

function record(value: unknown): Data { return typeof value === 'object' && value !== null && !Array.isArray(value) ? value as Data : {}; }
function rows(value: unknown): Data[] { return Array.isArray(value) ? value.map(record) : []; }
function text(value: unknown): string { return typeof value === 'string' ? value : ''; }
function number(value: unknown): number { return typeof value === 'number' ? value : 0; }
function flag(value: unknown): boolean { return value === true; }
function nested(value: unknown, key: string): Data { return record(record(value)[key]); }
function list(value: unknown, key: string): Data[] { return rows(record(value)[key]); }
function inputValue(form: HTMLFormElement, name: string): string { return String(new FormData(form).get(name) ?? '').trim(); }
function checked(form: HTMLFormElement, name: string): boolean { return new FormData(form).get(name) === 'on'; }
function today(): string { return new Date().toISOString().slice(0, 10); }

function capabilities(staff: Staff): Set<Capability> {
  const role = staff.role.code;
  if (role === 'ADMIN') return new Set<Capability>(['admin', 'kitchen', 'dispatch', 'driver', 'billing']);
  if (role === 'KITCHEN') return new Set<Capability>(['kitchen']);
  if (role === 'DISPATCH') return new Set<Capability>(['dispatch']);
  if (role === 'DRIVER') return new Set<Capability>(['driver']);
  return new Set();
}

function landing(staff: Staff): string {
  const allowed = capabilities(staff);
  if (allowed.has('admin')) return '/dashboard';
  if (allowed.has('kitchen')) return '/kitchen';
  if (allowed.has('dispatch')) return '/dispatch';
  return '/driver';
}

export function OperationsApp(): ReactNode {
  const [path, setPath] = useState('/');
  const [staff, setStaff] = useState<Staff | null>(null);
  const [loadingSession, setLoadingSession] = useState(true);

  const navigate = useCallback((next: string) => {
    window.history.pushState({}, '', next);
    setPath(next);
    window.scrollTo(0, 0);
  }, []);

  const restoreSession = useCallback(async () => {
    try {
      const response = await api.get<{ user: Staff }>('/auth/me');
      setStaff(response.user);
    } catch {
      setStaff(null);
    } finally {
      setLoadingSession(false);
    }
  }, []);

  useEffect(() => {
    setPath(window.location.pathname);
    void restoreSession();
    const pop = () => setPath(window.location.pathname);
    const unauthorized = () => { setStaff(null); navigate('/login'); };
    window.addEventListener('popstate', pop);
    window.addEventListener('fernleaf:unauthorized', unauthorized);
    return () => { window.removeEventListener('popstate', pop); window.removeEventListener('fernleaf:unauthorized', unauthorized); };
  }, [navigate, restoreSession]);

  if (loadingSession) return <main className="loading-screen">Restoring secure session…</main>;
  if (!staff) return <LoginPage onSuccess={(user) => { setStaff(user); navigate(landing(user)); }} />;
  if (path === '/' || path === '/login') { navigate(landing(staff)); return <main className="loading-screen">Opening workspace…</main>; }

  return <Shell staff={staff} path={path} navigate={navigate} onLogout={async () => {
    try { await api.post('/auth/logout'); } finally { setStaff(null); navigate('/login'); }
  }}>
    <PageRouter path={path} staff={staff} navigate={navigate} />
  </Shell>;
}

function LoginPage({ onSuccess }: { onSuccess: (staff: Staff) => void }): ReactNode {
  const [error, setError] = useState('');
  const [submitting, setSubmitting] = useState(false);
  async function submit(event: FormEvent<HTMLFormElement>): Promise<void> {
    event.preventDefault();
    const form = event.currentTarget;
    setSubmitting(true); setError('');
    try {
      const response = await api.post<{ user: Staff }>('/auth/login', { email: inputValue(form, 'email'), password: inputValue(form, 'password') });
      onSuccess(response.user);
    } catch (reason) { setError(messageFromError(reason)); }
    finally { setSubmitting(false); }
  }
  return <main className="login-page"><section className="login-card"><p className="eyebrow">Fernleaf Kitchen</p><h1>Operations admin</h1><p>Sign in with a seeded staff account to use the real backend.</p><form onSubmit={submit} className="form-stack"><label>Email<input name="email" type="email" defaultValue="admin@test.com" required autoComplete="email" /></label><label>Password<input name="password" type="password" defaultValue="Test@1234" required autoComplete="current-password" /></label>{error && <ErrorMessage message={error} />}<button className="button primary" disabled={submitting}>{submitting ? 'Signing in…' : 'Sign in'}</button></form><p className="muted small">Seeded roles: admin, kitchen, dispatch, and driver. Password: Test@1234.</p></section></main>;
}

function Shell({ staff, path, navigate, onLogout, children }: { staff: Staff; path: string; navigate: (path: string) => void; onLogout: () => Promise<void>; children: ReactNode }): ReactNode {
  const allowed = capabilities(staff);
  return <div className="app-shell"><aside className="sidebar"><button className="brand" onClick={() => navigate(landing(staff))}>Fernleaf<span>Operations</span></button><nav aria-label="Primary navigation">{pages.filter((page) => allowed.has(page.capability)).map((page) => <button key={page.path} onClick={() => navigate(page.path)} className={path === page.path || path.startsWith(`${page.path}/`) ? 'nav-link active' : 'nav-link'}>{page.label}</button>)}</nav><div className="user-panel"><strong>{staff.email}</strong><span>{staff.role.name}</span><button className="link-button" onClick={() => void onLogout()}>Log out</button></div></aside><div className="workspace"><header className="mobile-header"><button className="brand" onClick={() => navigate(landing(staff))}>Fernleaf</button><button className="link-button" onClick={() => void onLogout()}>Log out</button></header><main className="content">{children}</main></div></div>;
}

function PageRouter({ path, staff, navigate }: { path: string; staff: Staff; navigate: (path: string) => void }): ReactNode {
  if (path === '/dashboard') return <DashboardPage staff={staff} navigate={navigate} />;
  if (path === '/kitchen') return <KitchenPage staff={staff} />;
  if (path === '/dispatch') return <DispatchPage navigate={navigate} />;
  if (path === '/driver') return <DriverPage />;
  if (path === '/billing') return <BillingPage navigate={navigate} />;
  if (path.startsWith('/billing/invoices/')) return <InvoiceDetail id={path.split('/').at(-1) ?? ''} navigate={navigate} />;
  if (path === '/settings') return <SettingsPage />;
  if (path.startsWith('/reference/')) return <ReferencePage kind={path.split('/').at(-1) ?? 'allergens'} />;
  if (path === '/catalogue/dishes') return <DishesPage navigate={navigate} />;
  if (path.startsWith('/catalogue/dishes/')) return <DishDetail id={path.split('/').at(-1) ?? ''} navigate={navigate} />;
  if (path === '/catalogue/options') return <OptionsPage />;
  if (path === '/catalogue/option-groups') return <OptionGroupsPage />;
  if (path === '/pricing') return <PricingPage navigate={navigate} />;
  if (path.startsWith('/pricing/')) return <PricingDetail id={path.split('/').at(-1) ?? ''} />;
  if (path === '/companies') return <CompaniesPage navigate={navigate} />;
  if (path.startsWith('/companies/')) return <CompanyDetail id={path.split('/').at(-1) ?? ''} />;
  if (path === '/employees') return <EmployeesPage navigate={navigate} />;
  if (path.startsWith('/employees/')) return <EmployeeDetail id={path.split('/').at(-1) ?? ''} />;
  if (path === '/menu') return <MenuPage />;
  if (path === '/orders') return <OrdersPage navigate={navigate} />;
  if (path === '/orders/new') return <OrderEditor navigate={navigate} />;
  if (path.endsWith('/edit') && path.startsWith('/orders/')) return <OrderEditor id={path.split('/')[2]} navigate={navigate} />;
  if (path.startsWith('/orders/')) return <OrderDetail id={path.split('/').at(-1) ?? ''} navigate={navigate} />;
  return <Page title="Not found"><p>This route is not available.</p></Page>;
}

function Page({ title, actions, children }: { title: string; actions?: ReactNode; children: ReactNode }): ReactNode { return <><header className="page-header"><div><h1>{title}</h1></div><div className="page-actions">{actions}</div></header>{children}</>; }
function ErrorMessage({ message }: { message: string }): ReactNode { return <p className="message error" role="alert">{message}</p>; }
function SuccessMessage({ message }: { message: string }): ReactNode { return <p className="message success" role="status">{message}</p>; }
function Loading(): ReactNode { return <p className="muted">Loading…</p>; }
function Badge({ value }: { value: unknown }): ReactNode { const label = text(value) || 'Unknown'; return <span className={`badge ${label.toLowerCase().replaceAll('_', '-')}`}>{label.replaceAll('_', ' ')}</span>; }

function useLoad<T>(loader: () => Promise<T>, deps: unknown[]): { data: T | null; error: string; reload: () => Promise<void> } {
  const [data, setData] = useState<T | null>(null); const [error, setError] = useState('');
  const reload = useCallback(async () => { setError(''); try { setData(await loader()); } catch (reason) { setError(messageFromError(reason)); } }, deps); // eslint-disable-line react-hooks/exhaustive-deps
  useEffect(() => { void reload(); }, [reload]);
  return { data, error, reload };
}

function Metric({ label, value, href, navigate }: { label: string; value: ReactNode; href?: string; navigate?: (path: string) => void }): ReactNode { return <article className="metric">{href && navigate ? <button className="metric-link" onClick={() => navigate(href)}><span>{label}</span><strong>{value}</strong></button> : <><span>{label}</span><strong>{value}</strong></>}</article>; }

function DashboardPage({ staff, navigate }: { staff: Staff; navigate: (path: string) => void }): ReactNode {
  const type = capabilities(staff).has('admin') ? 'admin' : capabilities(staff).has('kitchen') ? 'kitchen' : capabilities(staff).has('dispatch') ? 'dispatch' : 'driver';
  const { data, error } = useLoad(() => api.get<Data>(`/dashboard/${type}`), [type]);
  return <Page title={type === 'admin' ? 'Operations dashboard' : `${type[0].toUpperCase()}${type.slice(1)} dashboard`} actions={<button className="button" onClick={() => navigate(type === 'driver' ? '/driver' : `/${type}`)}>Open workspace</button>}>{error && <ErrorMessage message={error} />}{!data ? <Loading /> : <DashboardData type={type} data={data} navigate={navigate} />}</Page>;
}

function DashboardData({ type, data, navigate }: { type: string; data: Data; navigate: (path: string) => void }): ReactNode {
  if (type === 'admin') return <><p className="muted">Kitchen-local date: {text(data.today)}</p><div className="metrics"><Metric label="Confirmed / delivered value" value={formatMoney(number(data.todayConfirmedOrderValue))} href="/orders" navigate={navigate} /><Metric label="Awaiting invoice" value={formatMoney(number(data.todayUninvoicedBillableValue))} href="/billing" navigate={navigate} /><Metric label="Kitchen late" value={number(data.lateKitchenOrderCount)} href="/kitchen" navigate={navigate} /><Metric label="Kitchen at risk" value={number(data.atRiskKitchenOrderCount)} href="/kitchen" navigate={navigate} /><Metric label="Unassigned drops" value={number(data.unassignedActiveDropCount)} href="/dispatch" navigate={navigate} /></div><Counts title="Orders by status" values={nested(data, 'ordersByStatus')} /><Counts title="Drops by status" values={nested(data, 'dropsByStatus')} /></>;
  if (type === 'kitchen') return <><p className="muted">Kitchen-local date: {text(data.today)}</p><div className="metrics"><Metric label="Prep units" value={number(nested(data, 'prepUnitCounts').total)} /><Metric label="Not started" value={number(nested(data, 'prepUnitCounts').notStarted)} /><Metric label="In progress" value={number(nested(data, 'prepUnitCounts').inProgress)} /><Metric label="Completed" value={number(nested(data, 'prepUnitCounts').completed)} /><Metric label="Late / at risk" value={`${number(data.lateOrderCount)} / ${number(data.atRiskOrderCount)}`} /></div><SimpleTable headers={['Station', 'Total', 'Not started', 'In progress', 'Completed']} rows={rows(data.stationBreakdown).map((row) => [text(row.stationName), number(row.total), number(row.notStarted), number(row.inProgress), number(row.completed)])} /></>;
  if (type === 'dispatch') return <><p className="muted">Kitchen-local date: {text(data.today)}</p><div className="metrics"><Metric label="Unassigned drivers" value={number(data.unassignedDriverCount)} /><Metric label="Delivery at risk" value={number(data.deliveryAtRiskCount)} /><Metric label="Overdue" value={number(data.overdueActiveDropCount)} /></div><Counts title="Drops by status" values={nested(data, 'dropsByStatus')} /></>;
  return <><p className="muted">Kitchen-local date: {text(data.today)}</p><div className="metrics"><Metric label="Today’s drops" value={number(data.totalDropCount)} /><Metric label="Remaining" value={number(data.remainingDeliveryCount)} /><Metric label="Delivered" value={number(data.deliveredCount)} /><Metric label="On time" value={number(data.onTimeDeliveredCount)} /></div>{record(data.nextDelivery).id && <section className="panel"><h2>Next delivery</h2><DropSummary drop={nested(data, 'nextDelivery')} /></section>}</>;
}

function Counts({ title, values }: { title: string; values: Data }): ReactNode { return <section className="panel"><h2>{title}</h2><div className="counts">{Object.entries(values).map(([key, value]) => <div key={key}><Badge value={key} /><strong>{number(value)}</strong></div>)}</div></section>; }
function SimpleTable({ headers, rows: cells }: { headers: string[]; rows: Array<Array<ReactNode>> }): ReactNode { return <div className="table-wrap"><table><thead><tr>{headers.map((header) => <th key={header}>{header}</th>)}</tr></thead><tbody>{cells.length ? cells.map((row, index) => <tr key={index}>{row.map((cell, cellIndex) => <td key={cellIndex}>{cell}</td>)}</tr>) : <tr><td colSpan={headers.length} className="muted">No records.</td></tr>}</tbody></table></div>; }

function KitchenPage({ staff }: { staff: Staff }): ReactNode {
  const [date, setDate] = useState(today()); const [stationId, setStationId] = useState('');
  const { data, error, reload } = useLoad(() => api.get<Data[]>(`/kitchen/board?deliveryDate=${date}${stationId ? `&stationId=${stationId}` : ''}`), [date, stationId]);
  const stations = useLoad(() => api.get<Data[]>('/reference-data/kitchen-stations'), []);
  const [message, setMessage] = useState('');
  const action = async (path: string, confirmMessage?: string) => {
    if (confirmMessage && !window.confirm(confirmMessage)) return;
    setMessage(''); try { await api.post(path); setMessage('Updated kitchen work.'); await reload(); } catch (reason) { setMessage(messageFromError(reason)); }
  };
  return <Page title="Kitchen board"><div className="toolbar"><label>Delivery date<input type="date" value={date} onChange={(event) => setDate(event.target.value)} /></label><label>Station<select value={stationId} onChange={(event) => setStationId(event.target.value)}><option value="">All stations</option><option value="UNASSIGNED">Unassigned</option>{rows(stations.data).map((station) => <option key={text(station.id)} value={text(station.id)}>{text(station.name)}</option>)}</select></label></div>{error && <ErrorMessage message={error} />}{message && (message === 'Updated kitchen work.' ? <SuccessMessage message={message} /> : <ErrorMessage message={message} />)}{!data ? <Loading /> : data.length === 0 ? <p className="empty">No confirmed prep work for this date.</p> : <div className="work-list">{data.map((order) => <section className="panel" key={text(order.id)}><div className="split"><div><h2>Order {shortId(text(order.id))} · {text(nested(order, 'company').name)}</h2><p className="muted">Delivery {timeFromMinutes(number(order.deliveryTimeMinutes))} · Kitchen ready target {formatDateTime(text(order.plannedKitchenReadyAt))}</p></div>{capabilities(staff).has('admin') && <button className="button danger" onClick={() => void action(`/kitchen/orders/${text(order.id)}/force-complete`, 'Force-complete all unfinished prep units?')}>Force complete</button>}</div><div className="unit-grid">{rows(order.units).map((unit) => <article className="unit" key={text(unit.id)}><div><strong>{text(nested(unit, 'dish').name)}</strong><span>{text(nested(unit, 'dish').sku)} · qty {number(unit.quantity)}</span></div><p>{rows(unit.selectedOptions).map((option) => `${text(option.optionGroupNameSnapshot)}: ${text(option.optionNameSnapshot)}`).join(', ') || 'No options'}</p><p><Badge value={unit.completedAt ? 'COMPLETED' : unit.startedAt ? 'IN_PROGRESS' : 'NOT_STARTED'} /> · {text(nested(unit, 'station').name)}</p>{flag(order.late) && <Badge value="LATE" />}{flag(order.atRisk) && <Badge value="AT_RISK" />}<div className="button-row">{!unit.startedAt && <button className="button" onClick={() => void action(`/kitchen/units/${text(unit.id)}/start`)}>Start</button>}{!unit.completedAt && <button className="button primary" onClick={() => void action(`/kitchen/units/${text(unit.id)}/complete`)}>Complete</button>}</div></article>)}</div></section>)}</div>}</Page>;
}

function DispatchPage({ navigate }: { navigate: (path: string) => void }): ReactNode {
  const [date, setDate] = useState(today()); const { data, error, reload } = useLoad(() => api.get<Data[]>(`/dispatch/board?deliveryDate=${date}`), [date]);
  const [notice, setNotice] = useState('');
  async function transition(id: string, operation: 'ready' | 'depart'): Promise<void> { setNotice(''); try { await api.post(`/dispatch/drops/${id}/${operation === 'ready' ? 'dispatch-ready' : 'out-for-delivery'}`); setNotice('Drop updated.'); await reload(); } catch (reason) { setNotice(messageFromError(reason)); } }
  async function assign(drop: Data): Promise<void> {
    const company = nested(drop, 'company');
    try {
      const detail = await api.get<Data>(`/companies/${text(company.id)}`);
      const driver = nested(detail, 'defaultDriver');
      if (!text(driver.id)) { setNotice('This Company has no configured default Driver. The backend has no staff-list endpoint for another selectable driver.'); return; }
      await api.patch(`/dispatch/drops/${text(drop.id)}/driver`, { driverId: text(driver.id) }); setNotice(`Assigned ${text(driver.email)}.`); await reload();
    } catch (reason) { setNotice(messageFromError(reason)); }
  }
  return <Page title="Dispatch board" actions={<button className="button" onClick={() => navigate('/driver')}>Driver view</button>}><div className="toolbar"><label>Delivery date<input type="date" value={date} onChange={(event) => setDate(event.target.value)} /></label></div>{error && <ErrorMessage message={error} />}{notice && (notice === 'Drop updated.' || notice.startsWith('Assigned') ? <SuccessMessage message={notice} /> : <ErrorMessage message={notice} />)}{!data ? <Loading /> : <div className="work-list">{data.map((drop) => <section className="panel" key={text(drop.id)}><div className="split"><div><h2>{text(nested(drop, 'company').name)} · {timeFromMinutes(number(drop.deliveryTimeMinutes))}</h2><p>{addressText(nested(drop, 'deliveryAddress'))}</p><p className="muted">{number(drop.orderCount)} order(s) · kitchen ready {formatDateTime(text(drop.kitchenReadyAt))} · planned dispatch {formatDateTime(text(drop.plannedDispatchReadyAt))}</p></div><Badge value={drop.status} /></div><div className="detail-grid"><span>Driver: {text(nested(drop, 'assignedDriver').email) || 'Unassigned'}</span><span>Ready: {formatDateTime(text(drop.dispatchReadyAt))}</span><span>Departed: {formatDateTime(text(drop.outForDeliveryAt))}</span><span>Delivered: {formatDateTime(text(drop.deliveredAt))}</span></div><div className="button-row">{!text(nested(drop, 'assignedDriver').id) && <button className="button" onClick={() => void assign(drop)}>Assign company default driver</button>}{text(drop.status) === 'WAITING_KITCHEN' && <button className="button primary" onClick={() => void transition(text(drop.id), 'ready')}>Mark dispatch ready</button>}{text(drop.status) === 'DISPATCH_READY' && text(nested(drop, 'assignedDriver').id) && <button className="button primary" onClick={() => void transition(text(drop.id), 'depart')}>Mark out for delivery</button>}</div></section>)}</div>}</Page>;
}

function DropSummary({ drop }: { drop: Data }): ReactNode { return <div className="detail-grid"><span><strong>{text(nested(drop, 'company').name)}</strong></span><span>{timeFromMinutes(number(drop.deliveryTimeMinutes))}</span><span>{addressText(nested(drop, 'deliveryAddress'))}</span><span><Badge value={drop.status} /></span></div>; }
function addressText(address: Data): string { return [text(address.label), text(address.addressLine1), text(address.addressLine2), text(address.city), text(address.stateRegion), text(address.postalCode)].filter(Boolean).join(', '); }

function DriverPage(): ReactNode {
  const { data, error, reload } = useLoad(() => api.get<Data[]>('/driver/drops/today'), []); const [openDrop, setOpenDrop] = useState(''); const [notice, setNotice] = useState('');
  async function deliver(event: FormEvent<HTMLFormElement>, id: string): Promise<void> { event.preventDefault(); if (!window.confirm('Mark this Drop delivered?')) return; const form = event.currentTarget; try { await api.post(`/driver/drops/${id}/deliver`, { note: inputValue(form, 'note') || undefined, photoUrl: inputValue(form, 'photoUrl') || undefined }); setOpenDrop(''); setNotice('Delivery recorded.'); await reload(); } catch (reason) { setNotice(messageFromError(reason)); } }
  return <Page title="My deliveries"><p className="muted">Only Drops assigned to your authenticated Driver account are shown.</p>{error && <ErrorMessage message={error} />}{notice && (notice === 'Delivery recorded.' ? <SuccessMessage message={notice} /> : <ErrorMessage message={notice} />)}{!data ? <Loading /> : data.length === 0 ? <p className="empty">No assigned Drops for today.</p> : <div className="driver-cards">{data.map((drop) => <article className="driver-card" key={text(drop.id)}><DropSummary drop={drop} /><p>Planned delivery: {formatDateTime(text(drop.plannedDeliveryAt))}</p>{text(drop.status) === 'OUT_FOR_DELIVERY' && (openDrop === text(drop.id) ? <form className="form-stack" onSubmit={(event) => void deliver(event, text(drop.id))}><label>Delivery note (optional)<textarea name="note" maxLength={1000} /></label><label>Photo URL (optional)<input name="photoUrl" type="url" /></label><div className="button-row"><button className="button primary">Mark delivered</button><button type="button" className="button" onClick={() => setOpenDrop('')}>Cancel</button></div></form> : <button className="button primary full" onClick={() => setOpenDrop(text(drop.id))}>Mark delivered</button>)}{text(drop.status) === 'DELIVERED' && <p><Badge value="DELIVERED" /> {drop.wasOnTime === true ? 'On time' : 'Late'}</p>}</article>)}</div>}</Page>;
}

function BillingPage({ navigate }: { navigate: (path: string) => void }): ReactNode {
  const [companyId, setCompanyId] = useState(''); const [selected, setSelected] = useState<string[]>([]); const [notice, setNotice] = useState('');
  const companies = useLoad(() => api.get<Data>('/companies?page=1&pageSize=100'), []); const invoices = useLoad(() => api.get<Data>('/billing/invoices?page=1&pageSize=50'), []);
  const uninvoiced = useLoad(() => companyId ? api.get<Data>(`/billing/companies/${companyId}/uninvoiced-orders?page=1&pageSize=100`) : Promise.resolve({ items: [] }), [companyId]);
  const orders = list(uninvoiced.data, 'items'); const selectedTotal = orders.filter((order) => selected.includes(text(order.id))).reduce((sum, order) => sum + number(order.totalMinorUnits), 0);
  async function createInvoice(): Promise<void> { if (!companyId || !selected.length) return; try { const invoice = await api.post<Data>('/billing/invoices', { companyId, orderIds: selected }); setSelected([]); setNotice('Invoice created.'); await Promise.all([invoices.reload(), uninvoiced.reload()]); navigate(`/billing/invoices/${text(invoice.id)}`); } catch (reason) { setNotice(messageFromError(reason)); } }
  return <Page title="Billing"><section className="panel"><h2>Create invoice from eligible Orders</h2><label>Company<select value={companyId} onChange={(event) => { setCompanyId(event.target.value); setSelected([]); }}><option value="">Choose a Company</option>{list(companies.data, 'items').map((company) => <option key={text(company.id)} value={text(company.id)}>{text(company.name)}</option>)}</select></label>{companyId && <><SimpleTable headers={['Select', 'Order', 'Delivery', 'Employee', 'Status', 'Amount']} rows={orders.map((order) => [<input key={text(order.id)} type="checkbox" checked={selected.includes(text(order.id))} onChange={() => setSelected((current) => current.includes(text(order.id)) ? current.filter((id) => id !== text(order.id)) : [...current, text(order.id)])} />, shortId(text(order.id)), formatDate(text(order.deliveryDate)), text(nested(order, 'employee').name), <Badge key="status" value={order.status} />, formatMoney(number(order.totalMinorUnits))])} /><div className="split"><strong>Selected total: {formatMoney(selectedTotal)}</strong><button className="button primary" disabled={!selected.length} onClick={() => void createInvoice()}>Create invoice ({selected.length})</button></div></>}</section>{notice && (notice === 'Invoice created.' ? <SuccessMessage message={notice} /> : <ErrorMessage message={notice} />)}<section className="panel"><h2>Invoices</h2>{invoices.error && <ErrorMessage message={invoices.error} />}<SimpleTable headers={['Invoice', 'Company', 'Status', 'Orders', 'Total', 'Created']} rows={list(invoices.data, 'items').map((invoice) => [<button key="id" className="link-button" onClick={() => navigate(`/billing/invoices/${text(invoice.id)}`)}>{shortId(text(invoice.id))}</button>, text(nested(invoice, 'company').name), <Badge key="status" value={invoice.status} />, number(nested(invoice, '_count').orders), formatMoney(number(invoice.totalMinorUnits)), formatDateTime(text(invoice.createdAt))])} /></section></Page>;
}

function InvoiceDetail({ id, navigate }: { id: string; navigate: (path: string) => void }): ReactNode {
  const { data, error, reload } = useLoad(() => api.get<Data>(`/billing/invoices/${id}`), [id]); const [notice, setNotice] = useState('');
  async function pay(): Promise<void> { if (!window.confirm('Mark this invoice paid? This cannot be repeated.')) return; try { await api.post(`/billing/invoices/${id}/paid`); setNotice('Invoice marked paid.'); await reload(); } catch (reason) { setNotice(messageFromError(reason)); } }
  return <Page title={`Invoice ${shortId(id)}`} actions={<button className="button" onClick={() => navigate('/billing')}>Back to Billing</button>}>{error && <ErrorMessage message={error} />}{notice && (notice === 'Invoice marked paid.' ? <SuccessMessage message={notice} /> : <ErrorMessage message={notice} />)}{!data ? <Loading /> : <><section className="panel"><div className="split"><div><h2>{text(nested(data, 'company').name)}</h2><p>Created {formatDateTime(text(data.createdAt))} · Paid {formatDateTime(text(data.paidAt))}</p><p className="muted">This is a frozen financial snapshot. Operational Order changes do not recalculate its total.</p></div><div><Badge value={data.status} /><h2>{formatMoney(number(data.totalMinorUnits))}</h2>{text(data.status) === 'OPEN' && <button className="button primary" onClick={() => void pay()}>Mark paid</button>}</div></div></section><section className="panel"><h2>Member Orders</h2><SimpleTable headers={['Order', 'Employee', 'Delivery', 'Status', 'Order total']} rows={rows(data.orders).map((order) => [shortId(text(order.id)), text(nested(order, 'employee').name), formatDate(text(order.deliveryDate)), <Badge key="status" value={order.status} />, formatMoney(number(order.totalMinorUnits))])} /></section></>}</Page>;
}

function SettingsPage(): ReactNode {
  const { data, error, reload } = useLoad(() => api.get<Data>('/settings/kitchen'), []); const holidays = useLoad(() => api.get<Data>('/settings/kitchen/holidays?page=1&pageSize=100'), []); const [notice, setNotice] = useState('');
  async function update(event: FormEvent<HTMLFormElement>): Promise<void> { event.preventDefault(); const form = event.currentTarget; try { await api.patch('/settings/kitchen', { timezone: inputValue(form, 'timezone'), workingDays: ['MONDAY', 'TUESDAY', 'WEDNESDAY', 'THURSDAY', 'FRIDAY', 'SATURDAY', 'SUNDAY'].filter((day) => checked(form, day)), cutoffWorkingDays: Number(inputValue(form, 'cutoffWorkingDays')), cutoffTime: inputValue(form, 'cutoffTime') }); setNotice('Kitchen settings saved.'); await reload(); } catch (reason) { setNotice(messageFromError(reason)); } }
  async function addHoliday(event: FormEvent<HTMLFormElement>): Promise<void> { event.preventDefault(); const form = event.currentTarget; try { await api.post('/settings/kitchen/holidays', { date: inputValue(form, 'date'), name: inputValue(form, 'name') || undefined }); form.reset(); await holidays.reload(); setNotice('Holiday added.'); } catch (reason) { setNotice(messageFromError(reason)); } }
  async function removeHoliday(id: string): Promise<void> { if (!window.confirm('Remove this kitchen holiday?')) return; try { await api.delete(`/settings/kitchen/holidays/${id}`); await holidays.reload(); } catch (reason) { setNotice(messageFromError(reason)); } }
  const days = rows(data?.workingDays).map((value) => text(value));
  return <Page title="Kitchen settings">{error && <ErrorMessage message={error} />}{notice && (notice.includes('saved') || notice.includes('added') ? <SuccessMessage message={notice} /> : <ErrorMessage message={notice} />)}{!data ? <Loading /> : <><section className="panel"><h2>Operating calendar and cutoff</h2><form className="form-grid" onSubmit={(event) => void update(event)}><label>Kitchen timezone<input name="timezone" defaultValue={text(data.timezone)} required /></label><label>Cutoff working days<input name="cutoffWorkingDays" type="number" min="0" defaultValue={number(data.cutoffWorkingDays)} required /></label><label>Cutoff time<input name="cutoffTime" type="time" defaultValue={text(data.cutoffTime)} required /></label><fieldset><legend>Working days</legend>{['MONDAY', 'TUESDAY', 'WEDNESDAY', 'THURSDAY', 'FRIDAY', 'SATURDAY', 'SUNDAY'].map((day) => <label className="check" key={day}><input type="checkbox" name={day} defaultChecked={days.includes(day)} />{day.slice(0, 3)}</label>)}</fieldset><button className="button primary">Save settings</button></form></section><section className="panel"><h2>Kitchen holidays</h2><form className="inline-form" onSubmit={(event) => void addHoliday(event)}><label>Date<input name="date" type="date" required /></label><label>Name<input name="name" placeholder="Optional closure name" /></label><button className="button">Add holiday</button></form><SimpleTable headers={['Date', 'Name', 'Action']} rows={list(holidays.data, 'items').map((holiday) => [formatDate(text(holiday.date)), text(holiday.name) || '—', <button key="delete" className="button danger" onClick={() => void removeHoliday(text(holiday.id))}>Remove</button>])} /></section></>}</Page>;
}

const referenceConfig: Record<string, { title: string; endpoint: string }> = {
  allergens: { title: 'Allergens', endpoint: '/reference-data/allergens' },
  'dietary-tags': { title: 'Dietary tags', endpoint: '/reference-data/dietary-tags' },
  'kitchen-stations': { title: 'Kitchen stations', endpoint: '/reference-data/kitchen-stations' },
};

function ReferencePage({ kind }: { kind: string }): ReactNode {
  const config = referenceConfig[kind] ?? referenceConfig.allergens; const { data, error, reload } = useLoad(() => api.get<Data[]>(config.endpoint), [config.endpoint]); const [notice, setNotice] = useState('');
  async function create(event: FormEvent<HTMLFormElement>): Promise<void> { event.preventDefault(); const form = event.currentTarget; try { await api.post(config.endpoint, { name: inputValue(form, 'name') }); form.reset(); setNotice('Reference value created.'); await reload(); } catch (reason) { setNotice(messageFromError(reason)); } }
  async function edit(item: Data): Promise<void> { const name = window.prompt(`Rename ${text(item.name)}`, text(item.name)); if (name === null) return; try { await api.patch(`${config.endpoint}/${text(item.id)}`, { name, isActive: !flag(item.isActive) ? true : undefined }); setNotice('Reference value updated.'); await reload(); } catch (reason) { setNotice(messageFromError(reason)); } }
  async function toggle(item: Data): Promise<void> { try { await api.patch(`${config.endpoint}/${text(item.id)}`, { isActive: !flag(item.isActive) }); await reload(); } catch (reason) { setNotice(messageFromError(reason)); } }
  return <Page title={config.title} actions={<div className="subnav"><Link href="/reference/allergens">Allergens</Link><Link href="/reference/dietary-tags">Dietary tags</Link><Link href="/reference/kitchen-stations">Stations</Link></div>}><section className="panel"><form className="inline-form" onSubmit={(event) => void create(event)}><label>Name<input name="name" required /></label><button className="button primary">Add {config.title.slice(0, -1)}</button></form>{error && <ErrorMessage message={error} />}{notice && (notice.includes('updated') || notice.includes('created') ? <SuccessMessage message={notice} /> : <ErrorMessage message={notice} />)}{!data ? <Loading /> : <SimpleTable headers={['Name', 'Status', 'Actions']} rows={data.map((item) => [text(item.name), <Badge key="status" value={flag(item.isActive) ? 'ACTIVE' : 'INACTIVE'} />, <div key="actions" className="button-row"><button className="button" onClick={() => void edit(item)}>Rename</button><button className="button" onClick={() => void toggle(item)}>{flag(item.isActive) ? 'Deactivate' : 'Activate'}</button></div>])} />}</section></Page>;
}

function DishesPage({ navigate }: { navigate: (path: string) => void }): ReactNode {
  const [creating, setCreating] = useState(false); const [search, setSearch] = useState(''); const { data, error, reload } = useLoad(() => api.get<Data>(`/catalogue/dishes?page=1&pageSize=100${search ? `&search=${encodeURIComponent(search)}` : ''}`), [search]);
  return <Page title="Catalogue · Dishes" actions={<div className="button-row"><button className="button" onClick={() => navigate('/catalogue/options')}>Options</button><button className="button" onClick={() => navigate('/catalogue/option-groups')}>Option groups</button><button className="button primary" onClick={() => setCreating((value) => !value)}>{creating ? 'Close form' : 'New dish'}</button></div>}>{creating && <DishForm onSaved={async (dish) => { await reload(); navigate(`/catalogue/dishes/${text(dish.id)}`); }} /> }<div className="toolbar"><label>Search<input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Name or SKU" /></label></div>{error && <ErrorMessage message={error} />}{!data ? <Loading /> : <SimpleTable headers={['Dish', 'SKU', 'Temperature', 'Cost', 'Station', 'Minimum', 'Status']} rows={list(data, 'items').map((dish) => [<button key="name" className="link-button" onClick={() => navigate(`/catalogue/dishes/${text(dish.id)}`)}>{text(dish.name)}</button>, text(dish.sku), text(dish.temperature), formatMoney(number(dish.costMinorUnits)), text(nested(dish, 'kitchenStation').name) || 'Unassigned', number(dish.minimumQuantity), <Badge key="status" value={flag(dish.isActive) ? 'ACTIVE' : 'INACTIVE'} />])} />}</Page>;
}

function DishForm({ dish, onSaved }: { dish?: Data; onSaved: (dish: Data) => Promise<void> }): ReactNode {
  const refs = useReferenceLists(); const [error, setError] = useState(''); const [saving, setSaving] = useState(false);
  async function submit(event: FormEvent<HTMLFormElement>): Promise<void> { event.preventDefault(); const form = event.currentTarget; setSaving(true); setError(''); try { const allergens = selectedValues(form, 'allergenIds'); const dietaryTags = selectedValues(form, 'dietaryTagIds'); const payload = { name: inputValue(form, 'name'), sku: inputValue(form, 'sku'), description: inputValue(form, 'description') || undefined, imageUrl: inputValue(form, 'imageUrl') || undefined, temperature: inputValue(form, 'temperature'), costMinorUnits: Number(inputValue(form, 'costMinorUnits')), minimumQuantity: Number(inputValue(form, 'minimumQuantity')), kitchenStationId: inputValue(form, 'kitchenStationId') || null, allergenIds: allergens, dietaryTagIds: dietaryTags, isActive: checked(form, 'isActive') }; const saved = dish ? await api.patch<Data>(`/catalogue/dishes/${text(dish.id)}`, payload) : await api.post<Data>('/catalogue/dishes', payload); await onSaved(saved); } catch (reason) { setError(messageFromError(reason)); } finally { setSaving(false); } }
  const allergenIds = rows(dish?.allergens).map((row) => text(row.id)); const tagIds = rows(dish?.dietaryTags).map((row) => text(row.id));
  return <section className="panel"><h2>{dish ? 'Edit dish' : 'Create dish'}</h2><form className="form-grid" onSubmit={(event) => void submit(event)}><label>Name<input name="name" defaultValue={text(dish?.name)} required /></label><label>SKU<input name="sku" defaultValue={text(dish?.sku)} required /></label><label>Temperature<select name="temperature" defaultValue={text(dish?.temperature) || 'HOT'}><option>HOT</option><option>COLD</option><option>AMBIENT</option></select></label><label>Internal cost (minor units)<input name="costMinorUnits" type="number" min="0" defaultValue={number(dish?.costMinorUnits)} required /></label><label>Minimum quantity<input name="minimumQuantity" type="number" min="1" defaultValue={number(dish?.minimumQuantity) || 1} required /></label><label>Kitchen station<select name="kitchenStationId" defaultValue={text(dish?.kitchenStationId)}><option value="">Unassigned</option>{refs.stations.map((item) => <option key={text(item.id)} value={text(item.id)}>{text(item.name)}</option>)}</select></label><label className="wide">Description<textarea name="description" defaultValue={text(dish?.description)} /></label><label className="wide">Image URL<input name="imageUrl" type="url" defaultValue={text(dish?.imageUrl)} /></label><MultiSelect name="allergenIds" label="Allergens" items={refs.allergens} defaults={allergenIds} /><MultiSelect name="dietaryTagIds" label="Dietary tags" items={refs.tags} defaults={tagIds} /><label className="check"><input name="isActive" type="checkbox" defaultChecked={dish ? flag(dish.isActive) : true} />Active</label>{error && <ErrorMessage message={error} />}<button className="button primary" disabled={saving}>{saving ? 'Saving…' : 'Save dish'}</button></form></section>;
}

function MultiSelect({ name, label, items, defaults }: { name: string; label: string; items: Data[]; defaults: string[] }): ReactNode { return <fieldset><legend>{label}</legend><select name={name} multiple defaultValue={defaults}>{items.map((item) => <option key={text(item.id)} value={text(item.id)}>{text(item.name)}</option>)}</select></fieldset>; }
function selectedValues(form: HTMLFormElement, name: string): string[] { return new FormData(form).getAll(name).map(String); }
function useReferenceLists(): { allergens: Data[]; tags: Data[]; stations: Data[] } { const allergies = useLoad(() => api.get<Data[]>('/reference-data/allergens'), []); const tags = useLoad(() => api.get<Data[]>('/reference-data/dietary-tags'), []); const stations = useLoad(() => api.get<Data[]>('/reference-data/kitchen-stations'), []); return { allergens: rows(allergies.data).filter((item) => flag(item.isActive)), tags: rows(tags.data).filter((item) => flag(item.isActive)), stations: rows(stations.data).filter((item) => flag(item.isActive)) }; }

function OptionsPage(): ReactNode {
  const { data, error, reload } = useLoad(() => api.get<Data[]>('/catalogue/options'), []); const refs = useReferenceLists(); const [notice, setNotice] = useState('');
  async function save(event: FormEvent<HTMLFormElement>): Promise<void> { event.preventDefault(); const form = event.currentTarget; try { await api.post('/catalogue/options', { name: inputValue(form, 'name'), costMinorUnits: Number(inputValue(form, 'costMinorUnits')), allergenIds: selectedValues(form, 'allergenIds'), dietaryTagIds: selectedValues(form, 'dietaryTagIds') }); form.reset(); setNotice('Option created.'); await reload(); } catch (reason) { setNotice(messageFromError(reason)); } }
  async function edit(option: Data): Promise<void> { const name = window.prompt('Option name', text(option.name)); if (name === null) return; try { await api.patch(`/catalogue/options/${text(option.id)}`, { name, isActive: flag(option.isActive) }); setNotice('Option updated.'); await reload(); } catch (reason) { setNotice(messageFromError(reason)); } }
  async function toggle(option: Data): Promise<void> { try { await api.patch(`/catalogue/options/${text(option.id)}`, { isActive: !flag(option.isActive) }); await reload(); } catch (reason) { setNotice(messageFromError(reason)); } }
  const tableRows: Array<Array<ReactNode>> = (data ?? []).map((option) => [
    text(option.name), formatMoney(number(option.costMinorUnits)), rows(option.allergens).map((row) => text(row.name)).join(', '), rows(option.dietaryTags).map((row) => text(row.name)).join(', '),
    <Badge key="status" value={flag(option.isActive) ? 'ACTIVE' : 'INACTIVE'} />,
    <div className="button-row" key="actions"><button className="button" onClick={() => void edit(option)}>Rename</button><button className="button" onClick={() => void toggle(option)}>{flag(option.isActive) ? 'Deactivate' : 'Activate'}</button></div>,
  ]);
  return <Page title="Catalogue · Options"><section className="panel"><h2>New reusable option</h2><form className="form-grid" onSubmit={(event) => void save(event)}><label>Name<input name="name" required /></label><label>Internal cost (minor units)<input name="costMinorUnits" type="number" min="0" required /></label><MultiSelect name="allergenIds" label="Allergens" items={refs.allergens} defaults={[]} /><MultiSelect name="dietaryTagIds" label="Dietary tags" items={refs.tags} defaults={[]} /><button className="button primary">Create option</button></form></section>{error && <ErrorMessage message={error} />}{notice && (notice.includes('created') || notice.includes('updated') ? <SuccessMessage message={notice} /> : <ErrorMessage message={notice} />)}{!data ? <Loading /> : <SimpleTable headers={['Name', 'Cost', 'Allergens', 'Dietary tags', 'Status', 'Actions']} rows={tableRows} />}</Page>;
}

function OptionGroupsPage(): ReactNode {
  const { data, error, reload } = useLoad(() => api.get<Data[]>('/catalogue/option-groups'), []); const options = useLoad(() => api.get<Data[]>('/catalogue/options'), []); const [selectedId, setSelectedId] = useState(''); const detail = useLoad(() => selectedId ? api.get<Data>(`/catalogue/option-groups/${selectedId}`) : Promise.resolve(null), [selectedId]); const [notice, setNotice] = useState('');
  async function create(event: FormEvent<HTMLFormElement>): Promise<void> { event.preventDefault(); try { const form = event.currentTarget; const group = await api.post<Data>('/catalogue/option-groups', { name: inputValue(form, 'name') }); setSelectedId(text(group.id)); event.currentTarget.reset(); await reload(); } catch (reason) { setNotice(messageFromError(reason)); } }
  async function replaceOptions(event: FormEvent<HTMLFormElement>): Promise<void> { event.preventDefault(); if (!selectedId) return; const form = event.currentTarget; const ids = selectedValues(form, 'optionIds'); try { await api.put(`/catalogue/option-groups/${selectedId}/options`, { options: ids.map((optionId, index) => ({ optionId, sortOrder: index + 1 })) }); setNotice('Group membership saved.'); await detail.reload(); } catch (reason) { setNotice(messageFromError(reason)); } }
  async function toggle(group: Data): Promise<void> { try { await api.patch(`/catalogue/option-groups/${text(group.id)}`, { isActive: !flag(group.isActive) }); await reload(); if (selectedId === text(group.id)) await detail.reload(); } catch (reason) { setNotice(messageFromError(reason)); } }
  const currentIds = rows(detail.data?.options).map((item) => text(item.id));
  return <Page title="Catalogue · Option groups"><div className="two-column"><section className="panel"><form className="inline-form" onSubmit={(event) => void create(event)}><label>Name<input name="name" required /></label><button className="button primary">Create group</button></form>{error && <ErrorMessage message={error} />}{!data ? <Loading /> : <div className="selection-list">{data.map((group) => <div key={text(group.id)} className={selectedId === text(group.id) ? 'selected' : ''}><button className="link-button" onClick={() => setSelectedId(text(group.id))}>{text(group.name)}</button><Badge value={flag(group.isActive) ? 'ACTIVE' : 'INACTIVE'} /><button className="button compact" onClick={() => void toggle(group)}>{flag(group.isActive) ? 'Deactivate' : 'Activate'}</button></div>)}</div>}</section><section className="panel"><h2>{text(detail.data?.name) || 'Select a group'}</h2>{notice && <ErrorMessage message={notice} />}{detail.data && <><p>Choose reusable Options in the order they should appear. The selected list order becomes backend `sortOrder`.</p><form className="form-stack" onSubmit={(event) => void replaceOptions(event)}><select name="optionIds" multiple defaultValue={currentIds}>{rows(options.data).filter((option) => flag(option.isActive)).map((option) => <option key={text(option.id)} value={text(option.id)}>{text(option.name)}</option>)}</select><button className="button primary">Save group options</button></form><SimpleTable headers={['Option', 'Cost', 'Order']} rows={rows(detail.data.options).map((item) => [text(item.name), formatMoney(number(item.costMinorUnits)), number(item.sortOrder)])} /></>}</section></div></Page>;
}

function DishDetail({ id, navigate }: { id: string; navigate: (path: string) => void }): ReactNode {
  const { data, error, reload } = useLoad(() => api.get<Data>(`/catalogue/dishes/${id}`), [id]); const groups = useLoad(() => api.get<Data[]>('/catalogue/option-groups'), []); const [editing, setEditing] = useState(false); const [notice, setNotice] = useState('');
  async function saveGroups(event: FormEvent<HTMLFormElement>): Promise<void> { event.preventDefault(); const form = event.currentTarget; const values = selectedValues(form, 'groupIds'); try { await api.put(`/catalogue/dishes/${id}/option-groups`, { groups: values.map((optionGroupId, index) => ({ optionGroupId, isRequired: checked(form, `required-${optionGroupId}`), sortOrder: index + 1 })) }); setNotice('Dish option groups saved.'); await reload(); } catch (reason) { setNotice(messageFromError(reason)); } }
  const configured = rows(data?.optionGroups); const configuredIds = configured.map((group) => text(group.id));
  return <Page title={text(data?.name) || 'Dish'} actions={<button className="button" onClick={() => navigate('/catalogue/dishes')}>Back to dishes</button>}>{error && <ErrorMessage message={error} />}{notice && (notice.includes('saved') ? <SuccessMessage message={notice} /> : <ErrorMessage message={notice} />)}{!data ? <Loading /> : <><section className="panel"><div className="split"><div><h2>{text(data.name)} <Badge value={flag(data.isActive) ? 'ACTIVE' : 'INACTIVE'} /></h2><p>{text(data.description)}</p><p>SKU {text(data.sku)} · {text(data.temperature)} · internal cost {formatMoney(number(data.costMinorUnits))}</p></div><button className="button" onClick={() => setEditing((value) => !value)}>{editing ? 'Close edit' : 'Edit dish'}</button></div>{editing && <DishForm dish={data} onSaved={async () => { setEditing(false); await reload(); }} />}</section><section className="panel"><h2>Dish option-group configuration</h2><p>Selected groups are attached in the displayed selection order. Mark required groups explicitly.</p><form className="form-stack" onSubmit={(event) => void saveGroups(event)}><select name="groupIds" multiple defaultValue={configuredIds}>{rows(groups.data).filter((group) => flag(group.isActive)).map((group) => <option key={text(group.id)} value={text(group.id)}>{text(group.name)}</option>)}</select>{rows(groups.data).filter((group) => flag(group.isActive)).map((group) => <label className="check" key={text(group.id)}><input type="checkbox" name={`required-${text(group.id)}`} defaultChecked={configured.find((item) => text(item.id) === text(group.id))?.isRequired === true} disabled={!configuredIds.includes(text(group.id))} />Required: {text(group.name)}</label>)}<button className="button primary">Save configuration</button></form><SimpleTable headers={['Group', 'Required', 'Order', 'Options']} rows={configured.map((group) => [text(group.name), flag(group.isRequired) ? 'Yes' : 'No', number(group.sortOrder), rows(group.options).map((option) => text(option.name)).join(', ')])} /></section></>}</Page>;
}

function PricingPage({ navigate }: { navigate: (path: string) => void }): ReactNode {
  const { data, error, reload } = useLoad(() => api.get<Data[]>('/pricing/tiers'), []); const [notice, setNotice] = useState('');
  async function create(event: FormEvent<HTMLFormElement>): Promise<void> { event.preventDefault(); const form = event.currentTarget; const source = inputValue(form, 'derivationSource'); try { const tier = await api.post<Data>('/pricing/tiers', { name: inputValue(form, 'name'), isDefault: checked(form, 'isDefault'), isActive: checked(form, 'isActive'), ...(source ? { derivationSource: source, baseTierId: inputValue(form, 'baseTierId') || undefined, multiplierBps: Number(inputValue(form, 'multiplierBps')) } : {}) }); await reload(); navigate(`/pricing/${text(tier.id)}`); } catch (reason) { setNotice(messageFromError(reason)); } }
  return <Page title="Pricing tiers"><section className="panel"><h2>Create tier</h2><form className="form-grid" onSubmit={(event) => void create(event)}><label>Name<input name="name" required /></label><label>Derivation<select name="derivationSource" defaultValue=""><option value="">Manual prices</option><option value="BASE_TIER">BASE_TIER</option><option value="ITEM_COST">ITEM_COST</option></select></label><label>Base tier<select name="baseTierId"><option value="">Not applicable</option>{rows(data).map((tier) => <option key={text(tier.id)} value={text(tier.id)}>{text(tier.name)}</option>)}</select></label><label>Multiplier (basis points)<input name="multiplierBps" type="number" min="1" placeholder="e.g. 11500" /></label><label className="check"><input name="isDefault" type="checkbox" />Default</label><label className="check"><input name="isActive" type="checkbox" defaultChecked />Active</label><button className="button primary">Create tier</button></form></section>{error && <ErrorMessage message={error} />}{notice && <ErrorMessage message={notice} />}{!data ? <Loading /> : <SimpleTable headers={['Tier', 'Default', 'Status', 'Derivation', 'Base tier', 'Multiplier']} rows={data.map((tier) => [<button key="name" className="link-button" onClick={() => navigate(`/pricing/${text(tier.id)}`)}>{text(tier.name)}</button>, flag(tier.isDefault) ? 'Yes' : 'No', <Badge key="status" value={flag(tier.isActive) ? 'ACTIVE' : 'INACTIVE'} />, text(tier.derivationSource) || 'MANUAL', text(tier.baseTierId) ? shortId(text(tier.baseTierId)) : '—', number(tier.multiplierBps) || '—'])} />}</Page>;
}

function PricingDetail({ id }: { id: string }): ReactNode {
  const { data, error, reload } = useLoad(() => api.get<Data>(`/pricing/tiers/${id}/matrix`), [id]); const [notice, setNotice] = useState('');
  async function updateTier(event: FormEvent<HTMLFormElement>): Promise<void> { event.preventDefault(); const form = event.currentTarget; try { await api.patch(`/pricing/tiers/${id}`, { name: inputValue(form, 'name'), isActive: checked(form, 'isActive'), isDefault: checked(form, 'isDefault') }); setNotice('Tier updated.'); await reload(); } catch (reason) { setNotice(messageFromError(reason)); } }
  async function savePrices(kind: 'dish' | 'option', items: Data[]): Promise<void> { const entries = items.map((item) => ({ [`${kind}Id`]: text(item.id), explicitPriceMinorUnits: item.explicitPriceMinorUnits === '' ? null : item.explicitPriceMinorUnits })); try { await api.put(`/pricing/tiers/${id}/${kind}-prices`, { entries }); setNotice('Price overrides saved.'); await reload(); } catch (reason) { setNotice(messageFromError(reason)); } }
  const [tab, setTab] = useState<'dishes' | 'options'>('dishes'); const [draft, setDraft] = useState<Data[]>([]);
  useEffect(() => { const values = rows(data?.[tab]).map((item) => ({ ...item, explicitPriceMinorUnits: item.explicitPriceMinorUnits === null ? '' : item.explicitPriceMinorUnits })); setDraft(values); }, [data, tab]);
  return <Page title={`Pricing matrix · ${text(nested(data, 'tier').name) || shortId(id)}`}>{error && <ErrorMessage message={error} />}{notice && (notice.includes('updated') || notice.includes('saved') ? <SuccessMessage message={notice} /> : <ErrorMessage message={notice} />)}{!data ? <Loading /> : <><section className="panel"><form className="inline-form" onSubmit={(event) => void updateTier(event)}><label>Name<input name="name" defaultValue={text(nested(data, 'tier').name)} required /></label><label className="check"><input name="isActive" type="checkbox" defaultChecked={flag(nested(data, 'tier').isActive)} />Active</label><label className="check"><input name="isDefault" type="checkbox" defaultChecked={flag(nested(data, 'tier').isDefault)} />Default</label><button className="button">Save tier</button></form></section><section className="panel"><div className="tabs"><button className={tab === 'dishes' ? 'active' : ''} onClick={() => setTab('dishes')}>Dishes</button><button className={tab === 'options' ? 'active' : ''} onClick={() => setTab('options')}>Options</button></div><p className="muted">Blank explicit price clears an override. Resolved price and availability are always returned by the backend.</p><div className="table-wrap"><table><thead><tr><th>Item</th><th>Cost</th><th>Explicit override</th><th>Resolved price</th><th>Availability</th></tr></thead><tbody>{draft.map((item, index) => <tr key={text(item.id)}><td>{text(item.name)} {text(item.sku) && <span className="muted">({text(item.sku)})</span>}</td><td>{formatMoney(number(item.costMinorUnits))}</td><td><input type="number" min="0" value={typeof item.explicitPriceMinorUnits === 'number' ? item.explicitPriceMinorUnits : ''} onChange={(event) => setDraft((current) => current.map((row, i) => i === index ? { ...row, explicitPriceMinorUnits: event.target.value === '' ? '' : Number(event.target.value) } : row))} /></td><td>{item.available === true ? formatMoney(number(item.priceMinorUnits)) : '—'}</td><td>{item.available === true ? text(item.source) : <Badge value={text(item.reason) || 'MISSING_PRICE'} />}</td></tr>)}</tbody></table></div><button className="button primary" onClick={() => void savePrices(tab === 'dishes' ? 'dish' : 'option', draft)}>Save {tab} overrides</button></section></>}</Page>;
}

