function OrdersPage({ navigate }: { navigate: (path: string) => void }): ReactNode {
  const [status, setStatus] = useState(''); const [search, setSearch] = useState(''); const [date, setDate] = useState(''); const [notice, setNotice] = useState('');
  const { data, error, reload } = useLoad(() => api.get<Data>(`/orders?page=1&pageSize=100${status ? `&status=${status}` : ''}${search ? `&search=${encodeURIComponent(search)}` : ''}${date ? `&deliveryFrom=${date}&deliveryTo=${date}` : ''}`), [status, search, date]);
  async function cutoff(): Promise<void> { if (!date || !window.confirm(`Process cutoff for ${date}?`)) return; try { const result = await api.post<Data>('/orders/cutoff/process', { deliveryDate: date }); setNotice(`Cutoff processed: ${number(result.confirmed)} confirmed, ${number(result.cancelled)} cancelled.`); await reload(); } catch (reason) { setNotice(messageFromError(reason)); } }
  return <Page title="Orders" actions={<button className="button primary" onClick={() => navigate('/orders/new')}>New Order</button>}><div className="toolbar"><label>Search<input value={search} onChange={(event) => setSearch(event.target.value)} /></label><label>Status<select value={status} onChange={(event) => setStatus(event.target.value)}><option value="">All statuses</option>{['DRAFT','PLACED','CONFIRMED','DELIVERED','CANCELLED','REJECTED'].map((value) => <option key={value}>{value}</option>)}</select></label><label>Delivery date<input type="date" value={date} onChange={(event) => setDate(event.target.value)} /></label><button className="button" disabled={!date} onClick={() => void cutoff()}>Process cutoff</button></div>{error && <ErrorMessage message={error} />}{notice && (notice.startsWith('Cutoff') ? <SuccessMessage message={notice} /> : <ErrorMessage message={notice} />)}{!data ? <Loading /> : <SimpleTable headers={['Order', 'Employee', 'Company', 'Delivery', 'Status', 'Total']} rows={list(data, 'items').map((order) => [<button key="id" className="link-button" onClick={() => navigate(`/orders/${text(order.id)}`)}>{shortId(text(order.id))}</button>, text(nested(order, 'employee').name), text(nested(order, 'company').name), `${formatDate(text(order.deliveryDate))} ${timeFromMinutes(number(order.deliveryTimeMinutes))}`, <Badge key="status" value={order.status} />, formatMoney(number(order.totalMinorUnits))])} />}</Page>;
}

interface DraftLine { dishId: string; quantity: number; combinations: Array<{ quantity: number; selections: Record<string, string> }>; }
function OrderEditor({ id, navigate }: { id?: string; navigate: (path: string) => void }): ReactNode {
  const existing = useLoad(() => id ? api.get<Data>(`/orders/${id}`) : Promise.resolve(null), [id]); const employees = useLoad(() => api.get<Data>('/employees?page=1&pageSize=100'), []); const [employeeId, setEmployeeId] = useState(''); const [deliveryDate, setDeliveryDate] = useState(''); const menu = useLoad(() => employeeId ? api.get<Data>(`/menu/preview/employees/${employeeId}`) : Promise.resolve(null), [employeeId]); const [lines, setLines] = useState<DraftLine[]>([]); const [notice, setNotice] = useState('');
  useEffect(() => { if (existing.data && !employeeId) { setEmployeeId(text(nested(existing.data, 'employee').id)); setDeliveryDate(text(existing.data.deliveryDate)); setLines(rows(existing.data.lines).map((line) => ({ dishId: text(line.dishId), quantity: number(line.quantity), combinations: rows(line.combinations).map((combo) => ({ quantity: number(combo.quantity), selections: Object.fromEntries(rows(combo.selectedOptions).map((item) => [text(item.optionGroupId), text(item.optionId)])) })) }))); } }, [existing.data, employeeId]);
  const dishes = rows(menu.data?.categories).flatMap((category) => rows(category.items));
  function addDish(dishId: string): void { if (!dishId || lines.some((line) => line.dishId === dishId)) return; setLines((current) => [...current, { dishId, quantity: 1, combinations: [{ quantity: 1, selections: {} }] }]); }
  function changeLine(index: number, patch: Partial<DraftLine>): void { setLines((current) => current.map((line, i) => i === index ? { ...line, ...patch } : line)); }
  function changeCombination(lineIndex: number, combinationIndex: number, patch: Partial<DraftLine['combinations'][number]>): void { setLines((current) => current.map((line, i) => i !== lineIndex ? line : { ...line, combinations: line.combinations.map((combo, j) => j === combinationIndex ? { ...combo, ...patch } : combo) })); }
  async function save(place: boolean): Promise<void> { if (!employeeId || !deliveryDate || !lines.length) { setNotice('Choose an Employee, delivery date, and at least one Dish.'); return; } const payload = { employeeId, deliveryDate, lines: lines.map((line) => ({ dishId: line.dishId, quantity: line.quantity, combinations: line.combinations.map((combo) => ({ quantity: combo.quantity, selections: Object.entries(combo.selections).filter(([, optionId]) => optionId).map(([optionGroupId, optionId]) => ({ optionGroupId, optionId })) })) })) }; try { const order = id ? await api.put<Data>(`/orders/${id}`, payload) : await api.post<Data>('/orders', payload); if (place) await api.post(`/orders/${text(order.id)}/place`); navigate(`/orders/${text(order.id)}`); } catch (reason) { setNotice(messageFromError(reason)); } }
  return <Page title={id ? `Edit Order ${shortId(id)}` : 'Create Order'} actions={<button className="button" onClick={() => navigate('/orders')}>Back to Orders</button>}><section className="panel"><div className="form-grid"><label>Employee<select value={employeeId} disabled={Boolean(id)} onChange={(event) => { setEmployeeId(event.target.value); setLines([]); }}><option value="">Choose Employee</option>{list(employees.data, 'items').filter((employee) => flag(employee.isActive)).map((employee) => <option key={text(employee.id)} value={text(employee.id)}>{text(employee.name)} · {text(nested(employee, 'company').name)}</option>)}</select></label><label>Delivery date<input type="date" value={deliveryDate} disabled={Boolean(id)} onChange={(event) => setDeliveryDate(event.target.value)} /></label></div>{menu.data && <><label>Add menu Dish<select defaultValue="" onChange={(event) => { addDish(event.target.value); event.currentTarget.value = ''; }}><option value="">Choose priced, available Dish</option>{dishes.map((item) => <option key={text(nested(item, 'dish').id)} value={text(nested(item, 'dish').id)}>{text(nested(item, 'dish').name)} · {formatMoney(number(item.resolvedPriceMinorUnits))}</option>)}</select></label><div className="work-list">{lines.map((line, lineIndex) => { const item = dishes.find((candidate) => text(nested(candidate, 'dish').id) === line.dishId); return <section className="panel inset" key={line.dishId}><div className="split"><h2>{text(nested(item, 'dish').name)}</h2><button className="button danger" onClick={() => setLines((current) => current.filter((_, i) => i !== lineIndex))}>Remove</button></div><label>Total quantity<input type="number" min={number(nested(item, 'dish').minimumOrderQuantity) || 1} value={line.quantity} onChange={(event) => changeLine(lineIndex, { quantity: Number(event.target.value) })} /></label>{line.combinations.map((combo, comboIndex) => <div className="combination" key={comboIndex}><label>Combination quantity<input type="number" min="1" value={combo.quantity} onChange={(event) => changeCombination(lineIndex, comboIndex, { quantity: Number(event.target.value) })} /></label>{rows(item?.optionGroups).map((group) => <label key={text(group.id)}>{text(group.name)} {flag(group.isRequired) ? '(required)' : '(optional)'}<select value={combo.selections[text(group.id)] ?? ''} onChange={(event) => changeCombination(lineIndex, comboIndex, { selections: { ...combo.selections, [text(group.id)]: event.target.value } })}><option value="">{flag(group.isRequired) ? 'Choose…' : 'None'}</option>{rows(group.options).map((option) => <option key={text(option.id)} value={text(option.id)}>{text(option.name)} +{formatMoney(number(option.resolvedPriceMinorUnits))}</option>)}</select></label>)}</div>)}<div className="button-row"><button className="button" onClick={() => changeLine(lineIndex, { combinations: [...line.combinations, { quantity: 1, selections: {} }] })}>Add combination</button><span className={line.combinations.reduce((sum, combo) => sum + combo.quantity, 0) === line.quantity ? 'success-text' : 'error-text'}>Combination quantity: {line.combinations.reduce((sum, combo) => sum + combo.quantity, 0)} / {line.quantity}</span></div></section>; })}</div></>}</section>{notice && <ErrorMessage message={notice} />}<div className="button-row"><button className="button" onClick={() => void save(false)}>Save Draft</button>{!id && <button className="button primary" onClick={() => void save(true)}>Create and Place</button>}</div></Page>;
}

function OrderDetail({ id, navigate }: { id: string; navigate: (path: string) => void }): ReactNode {
  const { data, error, reload } = useLoad(() => api.get<Data>(`/orders/${id}`), [id]); const [notice, setNotice] = useState('');
  async function action(path: string, body?: unknown): Promise<void> { try { await api.post(path, body); setNotice('Order updated.'); await reload(); } catch (reason) { setNotice(messageFromError(reason)); } }
  return <Page title={`Order ${shortId(id)}`} actions={<button className="button" onClick={() => navigate('/orders')}>Back</button>}>{error && <ErrorMessage message={error} />}{notice && (notice === 'Order updated.' ? <SuccessMessage message={notice} /> : <ErrorMessage message={notice} />)}{!data ? <Loading /> : <><section className="panel"><div className="split"><div><h2><Badge value={data.status} /> {text(nested(data, 'employee').name)} · {text(nested(data, 'company').name)}</h2><p>Delivery {formatDate(text(data.deliveryDate))} {timeFromMinutes(number(nested(data, 'delivery').deliveryTimeMinutes))} · cutoff {formatDateTime(text(data.cutoffAt))}</p><p>{addressText(nested(data, 'delivery'))} · {text(nested(data, 'delivery').packaging)}</p><p>Pricing tier snapshot: {text(nested(data, 'pricingTier').name)} · <strong>{formatMoney(number(data.totalMinorUnits))}</strong></p></div><div className="button-row">{['DRAFT','PLACED'].includes(text(data.status)) && <button className="button" onClick={() => navigate(`/orders/${id}/edit`)}>Edit</button>}{text(data.status) === 'DRAFT' && <button className="button primary" onClick={() => void action(`/orders/${id}/place`)}>Place</button>}{['DRAFT','PLACED','CONFIRMED'].includes(text(data.status)) && <button className="button danger" onClick={() => { if (window.confirm('Cancel this Order?')) void action(`/orders/${id}/cancel`); }}>Cancel</button>}</div></div></section><section className="panel"><h2>Historical food and price snapshots</h2>{rows(data.lines).map((line) => <div className="line-detail" key={text(line.id)}><h3>{text(line.dishNameSnapshot)} · {text(line.dishSkuSnapshot)} · qty {number(line.quantity)}</h3><p>Dish unit {formatMoney(number(line.dishUnitPriceMinorUnits))} · line total {formatMoney(number(line.lineTotalMinorUnits))} · station {text(line.kitchenStationNameSnapshot) || 'Unassigned'}</p>{rows(line.combinations).map((combo) => <p key={text(combo.id)}>Combination qty {number(combo.quantity)} · unit {formatMoney(number(combo.unitPriceMinorUnits))} · total {formatMoney(number(combo.totalMinorUnits))}: {rows(combo.selectedOptions).map((option) => `${text(option.optionGroupNameSnapshot)} ${text(option.optionNameSnapshot)} (${formatMoney(number(option.optionUnitPriceMinorUnits))})`).join(', ')}</p>)}</div>)}</section><section className="panel"><h2>Status timeline</h2><SimpleTable headers={['When', 'From', 'To', 'Actor', 'Note']} rows={rows(data.statusEvents).map((event) => [formatDateTime(text(event.occurredAt)), text(event.fromStatus) || '—', <Badge key="to" value={event.toStatus} />, text(nested(event, 'actorStaffUser').email) || 'System', text(event.note)])} /></section></>}</Page>;
}
